def maxFrequencyElements(nums: List[int]) -> int:
    # Count frequencies of each number
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Find the maximum frequency
    max_freq = 0
    for count in freq.values():
        if count > max_freq:
            max_freq = count

    # Count how many elements have this maximum frequency
    count_max_freq = 0
    for count in freq.values():
        if count == max_freq:
            count_max_freq += 1

    # Return the sum of frequencies of elements with max frequency
    return sum(freq[num] for num in freq if freq[num] == max_freq)

