def beautifulIndices(s: str, a: str, b: str, k: int) -> List[int]:
    n = len(s)

    # Find all indices where a occurs in s
    indices_a = []
    a_len = len(a)
    start = 0
    while start <= n - a_len:
        if s[start:start + a_len] == a:
            indices_a.append(start)
        start += 1

    # Find all indices where b occurs in s
    indices_b = []
    b_len = len(b)
    start = 0
    while start <= n - b_len:
        if s[start:start + b_len] == b:
            indices_b.append(start)
        start += 1

    result = []
    for i in indices_a:
        found = False
        for j in indices_b:
            if abs(i - j) <= k:
                result.append(i)
                found = True
                break
        if found:
            pass  # Already added to result

    return sorted(result)

