def minimumCost(nums):
    n = len(nums)
    if n < 3:
        return 0

    dp = [[0] * 3 for _ in range(n + 1)]

    # Initialize for the first subarray
    for i in range(n):
        dp[i + 1][1] = nums[i]

    # Initialize for the second subarray
    for i in range(1, n):
        for k in range(i):
            dp[i][2] = min(dp[k][1], dp[i][2])

    # Initialize for the third subarray
    for i in range(1, n):
        for k in range(i):
            dp[i][3] = min(dp[k][2], dp[i][3])

    return dp[n][3]

