class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        if not nums:
            return 0

        max_sum = float('-inf')
        num_sum = {}  # Maps a value to the maximum sum of a good subarray ending with that value
        seen_sum = {}  # Maps a value to the maximum sum of a good subarray ending with that value

        for i in range(len(nums)):
            current_sum = nums[i]
            if current_sum in num_sum:
                max_sum = max(max_sum, num_sum[current_sum])

            # Update num_sum for the current value
            if current_sum not in num_sum:
                num_sum[current_sum] = current_sum
            else:
                num_sum[current_sum] = max(num_sum[current_sum], current_sum)

            # Check for k
            if k > 0:
                target1 = current_sum + k
                if target1 in num_sum:
                    max_sum = max(max_sum, num_sum[target1])
                if target1 in num_sum and target1 != current_sum:
                    max_sum = max(max_sum, num_sum[target1])

            # Check for -k
            if k > 0:
                target2 = current_sum - k
                if target2 in num_sum:
                    max_sum = max(max_sum, num_sum[target2])
                if target2 in num_sum and target2 != current_sum:
                    max_sum = max(max_sum, num_sum[target2])

            # Update num_sum for the current value
            num_sum[current_sum] = max(num_sum[current_sum], current_sum)

        if max_sum == float('-inf'):
            return 0
        return max_sum

