from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        m = len(pattern)
        count = 0

        # Iterate over all possible starting positions i
        for i in range(n - m):
            # Check if the subarray starting at i matches the pattern
            match = True
            for k in range(m):
                idx = i + k + 1
                prev_idx = i + k
                if pattern[k] == 1:
                    if nums[idx] <= nums[prev_idx]:
                        match = False
                        break
                elif pattern[k] == -1:
                    if nums[idx] >= nums[prev_idx]:
                        match = False
                        break
                else:  # pattern[k] == 0
                    if nums[idx] != nums[prev_idx]:
                        match = False
                        break

            if match:
                count += 1

        return count

