class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return 0

        target_score = nums[0] + nums[1]
        operations = 0

        # Check if the first operation is valid
        if target_score != nums[0] + nums[1]:
            return 0

        for i in range(2, len(nums), 2):
            current_sum = nums[i-1] + nums[i]
            if current_sum == target_score:
                operations += 1
            else:
                break

        return operations

