class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        # Build a trie from all numbers in arr1
        class Node:
            def __init__(self):
                self.children = {}
                self.max_depth = 0

        self.root = Node()

        # Helper function to insert a number into the trie
        def insert(num_str):
            node = self.root
            for digit in num_str:
                if digit not in node.children:
                    node.children[digit] = Node()
                node = node.children[digit]
            node.max_depth = len(num_str)

        # Insert all numbers from arr1
        for num in arr1:
            insert(str(num))

        # Traverse the trie with each number from arr2
        max_len = 0
        for num in arr2:
            node = self.root
            for digit in num:
                if digit not in node.children:
                    break
                node = node.children[digit]
                # The common prefix length is the max depth of the node
                max_len = max(max_len, node.max_depth)

        return max_len

