import sys

def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        H = int(next(iterator))
        W = int(next(iterator))
        K = int(next(iterator))

        S = []
        for _ in range(H):
            S.append(next(iterator))
    except StopIteration:
        return

    # Initialize minimum operations to infinity
    min_ops = float('inf')

    # Helper to check if a segment contains 'x'
    def has_x(segment):
        return 'x' in segment

    # Helper to count '.' in a segment
    def count_dot(segment):
        return sum(1 for c in segment if c == '.')

    # Check Horizontal segments
    # Iterate over each row and each valid starting column
    for i in range(H):
        for j in range(W - K + 1):
            segment = S[i][j:j+K]
            if has_x(segment):
                continue

            # If no 'x', the cost is the number of '.' cells
            ops = count_dot(segment)
            if ops < min_ops:
                min_ops = ops

    # Check Vertical segments
    # Iterate over each column and each valid starting row
    for j in range(W):
        for i in range(H - K + 1):
            segment = S[i:i+K][j]
            if has_x(segment):
                continue

            ops = count_dot(segment)
            if ops < min_ops:
                min_ops = ops

    if min_ops == float('inf'):
        print("-1")
    else:
        print(min_ops)

if __name__ == '__main__':
    solve()

