import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        M = int(next(iterator))
        B = []
        for _ in range(M):
            B.append(int(next(iterator)))

        L = int(next(iterator))
        C = []
        for _ in range(L):
            C.append(int(next(iterator)))

        Q = int(next(iterator))
        X_values = []
        for _ in range(Q):
            X_values.append(int(next(iterator)))

        # Maximum possible sum is 100 * 100 * 100 = 1,000,000
        # We can use a boolean array to mark achievable sums.
        # Index corresponds to the sum value.
        max_sum = 100 * 100 * 100 # 10^6
        possible = [False] * (max_sum + 1)

        # Precompute all possible sums
        # We can optimize slightly by iterating and updating, but direct triple loop is fine given constraints.
        # Direct triple loop:
        for a in A:
            for b in B:
                for c in C:
                    s = a + b + c
                    if s <= max_sum:
                        possible[s] = True

        # Process queries
        results = []
        for x in X_values:
            if 0 <= x <= max_sum and possible[x]:
                results.append("Yes")
            else:
                results.append("No")

        print('\n'.join(results))

    except StopIteration:
        pass

if __name__ == '__main__':
    solve()

