                for end in range(start + 1, len(arr[j]) + 1):
                    sub = arr[j][start:end]
                    # Check if this substring is in arr[i]
                    if sub not in substrings[i]:
                        candidates.append(sub)

        # Among candidates, find the shortest lexicographically smallest
        if not candidates:
            answer.append("")
        else:
            # Sort by length first, then lexicographically
            candidates.sort(key=lambda x: (len(x), x))
            answer.append(candidates[0])

    return answer

