    def isSubstringPresent(self, s: str) -> bool:
        # Generate all substrings of length 2 from s
        substrings = [s[i:i+2] for i in range(len(s) - 1)]

        # Create the reverse of s
        reversed_s = s[::-1]

        # Check if any substring of length 2 is present in the reversed string
        return any(sub in reversed_s for sub in substrings)

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        if not s:
            return 0

        count = {}
        max_len = 0
        left = 0

        for right in range(len(s)):
            char = s[right]
            count[char] = count.get(char, 0) + 1

            while count[char] > 2:
                left_char = s[left]
                count[left_char] -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

        return max_len

