from collections import defaultdict

class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        n = len(nums)
        ans = [0] * n

        # Use a dictionary to store the current count of each ID
        current_counts = defaultdict(int)

        # Dictionary to store the maximum frequency seen so far for each ID
        max_freq = {}

        for i in range(n):
            val = nums[i]
            count = freq[i]

            if count > 0:
                # Add 'count' instances of 'val'
                current_counts[val] += count

                # Update max_freq for 'val'
                if val in max_freq and current_counts[val] >= max_freq[val]:
                    max_freq[val] = current_counts[val]
                else:
                    max_freq[val] = current_counts[val]
                    if val not in max_freq:  # Initialize if not present
                        max_freq[val] = current_counts[val]
            else:
                # Remove 'count' instances of 'val'
                current_counts[val] -= count

                # Update max_freq for 'val'
                if val in max_freq and current_counts[val] >= max_freq[val]:
                    max_freq[val] = current_counts[val]
                else:
                    max_freq[val] = current_counts[val]
                    if val not in max_freq:
                        max_freq[val] = current_counts[val]

            # The answer for this step is the maximum frequency among all IDs
            ans[i] = max(max_freq.values()) if max_freq else 0

        return ans

class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        # Calculate sum of digits of x
        digit_sum = 0
        temp_x = x
        while temp_x > 0:
            digit_sum += temp_x % 10
            temp_x //= 10

        # Check if x is divisible by its digit sum
        if x % digit_sum == 0:
            return digit_sum
        else:
            return -1

