class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)
        max_len = 1

        current_inc = 1
        current_dec = 1

        for i in range(1, n):
            if nums[i] > nums[i-1]:
                current_inc += 1
            elif nums[i] < nums[i-1]:
                current_dec += 1
            else:
                current_inc = 1
                current_dec = 1

            if current_inc > max_len:
                max_len = current_inc
            if current_dec > max_len:
                max_len = current_dec

        return max_len

