def getSmallestString(s: str, k: int) -> str:
    n = len(s)
    result = list(s)

    for i in range(n):
        current_char = result[i]
        remaining_k = k

        # Try to find the smallest character to change to
        best_char = None
        min_cost = float('inf')

        for c in range(ord('a'), ord('z') + 1):
            new_char = chr(c)
            cost = abs(ord(current_char) - ord(new_char))
            if cost < 26:
                cost += 26
                if cost <= remaining_k:
                    min_cost = cost
                    best_char = new_char
                    break

        if best_char is not None:
            k -= min_cost
            result[i] = best_char

    return "".join(result)

class Solution:
    def findLatestTime(self, s: str) -> str:
