import math

def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True

class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        prime_indices = []
        for i, num in enumerate(nums):
            if is_prime(num):
                prime_indices.append(i)

        if not prime_indices:
            return 0

        return prime_indices[-1] - prime_indices[0]

