        upper_count = Counter(word.upper())

        special_chars = 0
        for char in set(word):
            if char.islower() and char in lower_count and char in upper_count:
                special_chars += 1
            elif char.isupper() and char in lower_count and char in upper_count:
                special_chars += 1
            elif char in lower_count or char in upper_count:
                special_chars += 1

        return special_chars

