    vowels = set("aeiouAEIOU")

    # Condition 1: Length at least 3
    if len(word) < 3:
        return False

    # Condition 2: Only digits and English letters (uppercase and lowercase)
    if not all(word.isalnum()):
        return False

    # Condition 3: At least one vowel
