from math import gcd

def minAnagramLength(s: str) -> int:
    # Count frequency of each character in s
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Calculate GCD of all counts
    g = 0
    for c in counts.values():
        # math.gcd handles single numbers, but we need to start with 0 or handle first element
        # math.gcd(0, x) returns x.
        if g == 0:
            g = c
        else:
            g = gcd(g, c)

    # The length of t is |s| / g
    return len(s) // g

