class Solution:
    def sumDigitDifferences(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Count the frequency of each digit in the entire array
        digit_counts = [0] * 10
        for num in nums:
            for digit in str(num):
                digit_counts[int(digit)] += 1

        # Calculate the total digit differences
        total_digit_diff = 0
        total_pairs = n * (n - 1) // 2

        for digit in range(10):
            count = digit_counts[digit]
            same_pairs = count * (count - 1) // 2
            diff_pairs = total_pairs - same_pairs
            total_digit_diff += diff_pairs

        return total_digit_diff

