class Solution:
    def compressedString(self, word: str) -> str:
        comp = []
        i = 0
        n = len(word)

        while i < n:
            c = word[i]
            count = 1
            while i + count < n and word[i + count] == c:
                count += 1

            # Add the compressed prefix: "count" + "c"
            comp.append(str(count))
            comp.append(c)

            i += count

        return "".join(comp)

