def duplicateNumbersXOR(nums: List[int]) -> int:
    """
    Computes the bitwise XOR of all numbers that appear exactly twice in the input list.
    """
    # Dictionary to store the count of each number
    counts = {}

    # Count occurrences of each number
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    result = 0

    # Iterate through the counts to find numbers that appear exactly twice
    for num, count in counts.items():
        if count == 2:
            result ^= num

    return result

