class Solution:
    def countCompleteDayPairs(self, hours: List[int]) -> int:
        count = [0] * 24
        total_pairs = 0

        for hour in hours:
            r = hour % 24
            required = (24 - r) % 24
            total_pairs += count[required]
            count[r] += 1

        return total_pairs

from typing import List

class Solution:
    def minimumAverage(self, nums: List[int]) -> float:
        nums.sort()
        n = len(nums)
        averages = []

        for _ in range(n // 2):
            min_val = nums[0]
            max_val = nums[-1]
            averages.append((min_val + max_val) / 2.0)
            nums.pop(0)
            nums.pop()

        return min(averages)

