def minimumArea(grid):
    if not grid or not grid[0]:
        return 0

    min_r = len(grid)
    max_r = -1
    min_c = len(grid[0])
    max_c = -1

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 1:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    height = max_r - min_r + 1
    width = max_c - min_c + 1
    return height * width

