def getEncryptedString(s: str, k: int) -> str:
    n = len(s)
    result = []
    for i, char in enumerate(s):
        # Calculate the index in the original string corresponding to the k-th character after char
        new_index = (i + k) % n
        result.append(s[new_index])
    return "".join(result)

