class Solution:
    def getSmallestString(self, s: str) -> str:
        n = len(s)
        res = s[:]

        for i in range(n - 1):
            digit1 = int(s[i])
            digit2 = int(s[i+1])

            if digit1 % 2 == digit2 % 2:
                # Check if swapping makes the string lexicographically smaller
                if int(s[i]) > int(s[i+1]):
                    res[i] = s[i+1]
                    res[i+1] = s[i]
                    break

        return res

