def nonSpecialCount(l: int, r: int) -> int:
    import math

    # Precompute all special numbers (cubes of primes) up to 10^9
    limit = 1000  # since p^3 <= 10^9 => p <= 1000
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False

    special = set()
    for p in range(2, limit + 1):
        if is_prime[p]:
            cube = p * p * p
            if cube <= 10**9:
                special.add(cube)

    # Count special numbers in [l, r]
    count_special = 0
    for s in special:
        if l <= s <= r:
            count_special += 1

    total = r - l + 1
    return total - count_special

