from typing import List

def finalPositionOfSnake(n: int, commands: List[str]) -> int:
    current_pos = 0

    for command in commands:
        if command == "UP":
            current_pos = (current_pos // n) - 1 * n + (current_pos % n)
        elif command == "DOWN":
            current_pos = (current_pos // n) + 1 * n + (current_pos % n)
        elif command == "RIGHT":
            current_pos = current_pos + 1
        elif command == "LEFT":
            current_pos = current_pos - 1

    return current_pos

