def solve():
    try:
        line = input().split()
        if len(line) < 3:
            return
        s_ab, s_ac, s_bc = line[0], line[1], line[2]
    except EOFError:
        return

    in_degree = [0, 0, 0]
    adj = [[] for _ in range(3)]

    # S_AB
    if s_ab == '<':
        adj[0].append(1)
        in_degree[1] += 1
    else:
        adj[1].append(0)
        in_degree[0] += 1

    # S_AC
    if s_ac == '<':
        adj[0].append(2)
        in_degree[2] += 1
    else:
        adj[2].append(0)
        in_degree[0] += 1

    # S_BC
    if s_bc == '<':
        adj[1].append(2)
        in_degree[2] += 1
    else:
        adj[2].append(1)
        in_degree[1] += 1

    # Topological Sort
    queue = [i for i in range(3) if in_degree[i] == 0]
    order = []
    idx_in_queue = 0

    while idx_in_queue < len(queue):
        u = queue[idx_in_queue]
        idx_in_queue += 1
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Middle brother is the one at index 1 of the sorted order
    if len(order) > 1:
        print(order[1])
    else:
        print(order[0])

