def countKConstraintSubstrings(s: str, k: int) -> int:
    n = len(s)
    result = 0

    for i in range(n):
        zeros = 0
        ones = 0
        length = 0

        while i < n:
            if s[i] == '0':
                zeros += 1
            else:
                ones += 1

            length += 1

            if zeros <= k or ones <= k:
                result += length
            else:
                i += 1

    return result

