def countPairs(nums):
    count = 0
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            # If numbers are the same, they are almost equal
            if nums[i] == nums[j]:
                count += 1
            else:
                # Check if they are cyclic permutations by comparing sorted digits
                s1 = sorted(str(nums[i]))
                s2 = sorted(str(nums[j]))
                if s1 == s2:
                    count += 1
    return count

