from typing import List

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        heap = []
        results = []

        for x, y in queries:
            dist = abs(x) + abs(y)
            heapq.heappush(heap, dist)

            if len(heap) < k:
                results.append(-1)
            else:
                results.append(heapq.heappop(heap))

        return results

def maxScore(a, b):
    # Sort b based on the sign of the corresponding coefficient in a
    # Elements with positive coefficients come first, then negative
    b_sorted = sorted(b, key=lambda x: (a[0] > 0 and x >= 0, a[0] < 0 and x < 0))

    # dp[j] stores the maximum score using the first j elements of b_sorted
    dp = [-float('inf')] * (len(b_sorted) + 1)
    dp[0] = 0

    for i in range(len(b_sorted)):
        # Current element in b_sorted is b_sorted[i]
        # If a[k] > 0, we want to pick b_sorted[i] as early as possible
        # If a[k] < 0, we want to pick b_sorted[i] as late as possible
        for k in range(4):
            if a[k] > 0:
                if dp[i] != -float('inf'):
                    dp[i+1] = max(dp[i+1], dp[i] + b_sorted[i])
            elif a[k] < 0:
                if dp[i+1] != -float('inf'):
                    dp[i+1] = max(dp[i+1], dp[i+1] + b_sorted[i])
            else:
                # If a[k] is 0, it doesn't affect the score
                pass

    return max(dp)

