from typing import List

class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        if not target:
            return 0

        # Build a set of all unique prefixes of all words
        prefixes = set()
        for word in words:
            for i in range(1, len(word) + 1):
                prefixes.add(word[:i])

        # Map from prefix to its next prefix in the same word
        prefix_map = {}
        for word in words:
            for i in range(1, len(word) + 1):
                prefix = word[:i]
                if prefix in word[1:]:  # Check if the prefix ends at the current position
                    next_prefix = word[i:]
                    prefix_map[prefix] = next_prefix

        # BFS initialization
        distances = {"" : 0}
        queue = deque([""])

        while queue:
            current = queue.popleft()
            dist = distances[current]

            if current == target:
                return dist

            # Try extending from current with each word
            for word in words:
                if current not in prefix_map:
                    continue
                next_prefix = prefix_map[current]
                if next_prefix not in prefixes:
                    continue

                next_dist = dist + 1
                if next_dist not in distances or distances[next_prefix] > next_dist:
                    distances[next_prefix] = next_dist
                    queue.append(next_prefix)

        return -1

from typing import List

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        results = []

        for i in range(n - k + 1):
            subarray = nums[i:i+k]

            # Check if subarray is sorted in ascending order
            is_sorted = True
            for j in range(len(subarray) - 1):
                if subarray[j] > subarray[j+1]:
                    is_sorted = False
                    break

            if not is_sorted:
                results.append(-1)
                continue

            # Check if elements are consecutive
            is_consecutive = True
            for j in range(len(subarray) - 1):
                if subarray[j+1] - subarray[j] != 1:
                    is_consecutive = False
                    break

            if is_consecutive:
                results.append(subarray[-1])
            else:
                results.append(-1)

        return results

def stringHash(s: str, k: int) -> str:
    result = []
    for i in range(0, len(s), k):
        chunk = s[i : i + k]
        total_hash = 0
        for char in chunk:
            total_hash += ord(char) - ord('a')

        hashed_char = chr(total_hash % 26 + ord('a'))
        result.append(hashed_char)

    return "".join(result)

