def sum_of_digits(n: int) -> int:
    """Calculates the sum of the digits of an integer."""
    total = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total

def min_element(nums: list[int]) -> int:
    """
    Replaces each element in nums with the sum of its digits
    and returns the minimum value among them.
    """
    if not nums:
        return 0

    min_val = float('inf')

    for num in nums:
        digit_sum = sum_of_digits(num)
        if digit_sum < min_val:
            min_val = digit_sum

    return min_val

