def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n_str = next(iterator)
        N = int(n_str)

        K = []
        for _ in range(N):
            K.append(int(next(iterator)))
    except StopIteration:
        return

    total_sum = sum(K)
    min_max = total_sum  # Initialize with a value larger than or equal to any possible sum

    # Iterate through all possible subsets (2^N)
    # Since N <= 20, 2^20 is approx 10^6, which is feasible.
    num_subsets = 1 << N

    for i in range(num_subsets):
        current_sum = 0
        # Calculate sum for the current subset
        for j in range(N):
            if (i >> j) & 1:
                current_sum += K[j]

        # Calculate the max of the two groups
        max_val = max(current_sum, total_sum - current_sum)

        if max_val < min_max:
            min_max = max_val

    print(min_max)

