from typing import List

class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        if k == 1:
            return len(s) * (len(s) + 1) // 2

        count = 0
        for i, char in enumerate(s):
            if s.count(char) < k:
                continue

            cnt = s.count(char)
            if cnt >= k:
                for j in range(i, cnt):
                    start = j - k + 1
                    if start > i - k:
                        count += cnt * (j + 1) - (i - k + 1 - j)

        return count

