class Solution:
    def maxScore(self, nums: List[int]) -> int:
        if not nums:
            return 0

        def compute_lcm(a, b):
            return abs(a * b) // gcd(a, b)

        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        initial_lcm = nums[0]
        initial_gcd = nums[0]

        for i in range(1, len(nums)):
            initial_lcm = compute_lcm(initial_lcm, nums[i])
            initial_gcd = gcd(initial_gcd, nums[i])

        max_score = initial_lcm * initial_gcd

        for i in range(len(nums)):
            # Calculate new LCM and GCD after removing nums[i]
            new_lcm = nums[0]
            new_gcd = nums[0]

            for j in range(1, len(nums)):
                if j != i:
                    new_lcm = compute_lcm(new_lcm, nums[j])
                    new_gcd = gcd(new_gcd, nums[j])

            score = new_lcm * new_gcd
            if score > max_score:
                max_score = score

        return max_score

