from typing import List

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n = len(moveTime)
        m = len(moveTime[0])
        dist = [[float('inf')] * m for _ in range(n)]
        dist[0][0] = 0

        pq = [(0, 0, 0)]  # (current_time, r, c)

        while pq:
            current_time, r, c = heapq.heappop(pq)

            if current_time > dist[r][c]:
                continue

            if r == n - 1 and c == m - 1:
                return current_time

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    new_time = current_time + moveTime[nr][nc] - (current_time - moveTime[r][c])
                    if new_time < dist[nr][nc]:
                        dist[nr][nc] = new_time
                        heapq.heappush(pq, (new_time, nr, nc))

        return dist[n-1][m-1]

def hasIncreasingSubarrays(nums: List[int], k: int) -> bool:
    n = len(nums)

    # Check all possible starting positions for the first subarray
    for i in range(n - k + 1):
        # Check if the subarray starting at i is strictly increasing
        is_inc1 = True
        for j in range(k - 1):
            if nums[i + j] >= nums[i + j + 1]:
                is_inc1 = False
                break

        if is_inc1:
            # Check the next subarray starting at i + k
            next_i = i + k
            if next_i < n:
                is_inc2 = True
                for j in range(k - 1):
                    if nums[next_i + j] >= nums[next_i + j + 1]:
                        is_inc2 = False
                        break

                if is_inc2:
