class Solution:
    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        # Count the frequency of each element
        from collections import Counter
        counter = Counter(nums)

        max_freq = 0
        for freq in counter.values():
            max_freq = max(max_freq, freq)

        # Calculate the number of operations needed to increase the current max frequency
        needed = 0
        for freq in counter.values():
            if freq > max_freq:
                needed = freq - max_freq
                break

        # If we have enough operations to increase the current max frequency,
        # we can potentially expand it further.
        if needed <= numOperations:
            max_freq += 2 * k

        # Check if the current max frequency is still the best
        if max_freq >= numOperations:
            for freq in counter.values():
                if freq > max_freq:
                    max_freq = freq

        return max_freq

def shiftDistance(s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
    # Convert each character to its 0-based index
    s_indices = [ord(c) - ord('a') for c in s]
    t_indices = [ord(c) - ord('a') for c in t]

    total_cost = 0
    for i in range(len(s)):
        diff = t_indices[i] - s_indices[i]
        if diff < 0:
            total_cost += previousCost[s_indices[i]]
        else:
            total_cost += nextCost[s_indices[i]]

    return total_cost

