class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        if not points:
            return -1

        n = len(points)
        # Identify points that are inside any other point
        inside = [False] * n
        for i in range(n):
            for j in range(i + 1, n):
                x1, y1 = points[i]
                x2, y2 = points[j]
                if (x1 < x2 and x1 < x2 and y1 < y2) or (x1 > x2 and x1 > x2 and y1 > y2):
                    inside[i] = True
                    inside[j] = True

        # Filter out invalid points
        valid_points = [p for i, p in enumerate(points) if not inside[i]]

        if len(valid_points) < 4:
            return -1

        max_area = -1

        # Check for collinear points
        for i in range(len(valid_points)):
            for j in range(i + 1, len(valid_points)):
                p1 = valid_points[i]
                p2 = valid_points[j]

                if p1[0] == p2[0] or p1[1] == p2[1]:
                    # Found a pair of adjacent sides
                    x1, y1 = p1
                    x2, y2 = p2

                    # Check if there are other points with the same x or y
                    found_rect = False
                    if x1 == x2:
                        for k in range(len(valid_points)):
                            if k != i and k != j and valid_points[k][0] == x1 and valid_points[k][0] == x2:
                                found_rect = True
                                break
                    elif y1 == y2:
                        for k in range(len(valid_points)):
                            if k != i and k != j and valid_points[k][1] == y1 and valid_points[k][1] == y2:
                                found_rect = True
                                break

                    if found_rect:
                        # Calculate area
                        area = abs(x1 - x2) * abs(y1 - y2)
                        max_area = max(max_area, area)

        return max_area
