from collections import deque

def isPrime(num):
    if num < 2:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def minOperations(n: int, m: int) -> int:
    # Check if n or m is prime
    if isPrime(n) or isPrime(m):
        return -1

    # BFS to find the path
    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        current, cost = queue.popleft()

        if current == m:
            return cost

        # Generate next numbers
        # Try increasing
        next_val = current + 1
        if next_val <= 10000 and not isPrime(next_val) and next_val not in visited:
            visited.add(next_val)
            queue.append((next_val, cost + 1))

        # Try decreasing
        next_val = current - 1
        if next_val >= 0 and not isPrime(next_val) and next_val not in visited:
            visited.add(next_val)
            queue.append((next_val, cost + 1))

    return -1

