def calculateScore(self, s: str) -> int:
    # Create a mapping from each character to its mirror counterpart
    mirror_map = {}
    for i, char in enumerate(sorted(s)):
        mirror_map[char] = s[len(s) - 1 - i]

    total_score = 0
    # List to keep track of unmarked indices
    unmarked_indices = []

    # Iterate through the string to process each character
    for i, char in enumerate(s):
        # If the character is already marked, skip it
        if char in unmarked_indices:
            continue

        # Find the closest unmarked index j to the left with s[j] == mirror(s[i])
        j = -1
        for idx in unmarked_indices:
            if idx < i and mirror_map[s[idx]] == char:
                j = idx
                break

        if j != -1:
            total_score += i - j
            unmarked_indices.remove(j)
            unmarked_indices.append(i)

    return total_score

