                        return True

        return False

from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        if not nums:
            return 0

        max_len = 0
        V = 301  # Maximum value + 1

        # dp[v][i] is not needed, we only need the maximum length ending with value v
        # Initialize dp with a value indicating no subsequence found yet
        dp = [[0] * V for _ in range(len(nums) + 1)]

        for i in range(len(nums)):
            num = nums[i]
            for v in range(V):
                if v < num:
                    dp[v] = max(dp[v], dp[v] + 1)
                elif v >= num:
                    if dp[v] > 0 and num - v < dp[v]:
                        dp[v] = dp[v] + 1
            if dp[v] > max_len:
                max_len = dp[v]

        return max_len

