def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))

        S = []
        for _ in range(N):
            S.append(next(iterator))

        T = []
        for _ in range(M):
            T.append(next(iterator))

    except StopIteration:
        return

    # Iterate through all possible top-left positions (a, b)
    # a is the 1-based starting row, b is the 1-based starting column
    for a in range(1, N - M + 2):
        for b in range(1, N - M + 2):
            # Check if the subgrid starting at (a, b) matches T
            match = True
            for i in range(M):
                for j in range(M):
                    # S indices: row a+i-1, col b+j-1 (1-based)
                    # T indices: row i, col j (1-based)
                    if S[a+i-1][b+j-1] != T[i][j]:
                        match = False
                        break
                if not match:
                    break
            if match:
                print(f"{a} {b}")
                return

