import sys

def solve():
    # Read N from standard input
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        N = int(input_data[0])
    except ValueError:
        return

    # Initialize the grid with all white ('.')
    grid = [['.' for _ in range(N)] for _ in range(N)]

    # Iterate through each row i from 1 to N
    for i in range(1, N + 1):
        j = N + 1 - i

        # Condition for filling
        if i <= j:
            # Determine color based on parity of i
            if i % 2 != 0: # i is odd
                color = '#'
            else: # i is even
                color = '.'

            # Fill the rectangle [i, j] x [i, j]
            # We iterate through the sub-rectangle
            for r in range(i, j + 1):
                for c in range(i, j + 1):
                    grid[r][c] = color

    # Print the resulting grid
    for row in grid:
        print("".join(row))

