    for _ in range(n):
        try:
            val = int(next(iterator))
            a.append(val)
        except StopIteration:
            break

    # Count frequencies of each number
    counts = Counter(a)

    valid_labels = []
    for i, val in enumerate(a):
        # Check if the number val appears exactly once
        if counts[val] == 1:
            valid_labels.append(i + 1) # Store 1-based label

    if not valid_labels:
        print("-1")
    else:
        # Find the maximum label among valid ones
        print(max(valid_labels))

