from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        if n % 2 != 0:
            raise ValueError("n must be even")

        # Precompute costs for color 0, 1, 2
        costs = [0, 0, 0]
        for i in range(n):
            for c in range(3):
                costs[c] += cost[i][c]

        # dp[i][c] represents the minimum cost to paint houses 0 to i-1
        # with the i-th house painted with color c
        dp = [[0] * 3 for _ in range(n)]

        # Initialize for the first house
        for c in range(3):
            if n == 2:
                dp[0][c] = costs[c]
            else:
                dp[0][c] = costs[c]

        # Fill DP table
        for i in range(1, n):
            # Determine which colors are valid for house i-1
            prev_colors = set()
            for j in range(3):
                if j == 1:
                    continue
                if n - 1 - (i - 1) == 0:
                    continue
                prev_colors.add(j)

            for c in range(3):
                if c not in prev_colors:
                    dp[i][c] = costs[c]
                else:
                    # Check condition for house n-1-(i-1)
                    if n - 1 - (i - 1) != 0:
                        if cost[n - 1 - (i - 1)][c] != 0:
                            if n - 1 - (i - 1) == 0:
                                dp[i][c] = min(dp[i][c], dp[i-1][c])
                            else:
                                dp[i][c] = min(dp[i][c], dp[i-1][c] + cost[n - 1 - (i - 1)][c])
                    else:
                        dp[i][c] = costs[c]

        return min(dp[n-1])

